package it.servizidigitali.gestionebandi.operatore.frontend.enums;

import java.util.Objects;

public enum DomandaBandoTabEnum {
    IN_ARRIVO("in.arrivo"),
    IN_LAVORAZIONE("in.lavorazione"),
    IN_ITINERE_CHIUSI("in.itinere.chiusi");

    private final String key;

    DomandaBandoTabEnum(String key) {
        this.key = key;
    }

    public String getKey() {
        return key;
    }

    public static DomandaBandoTabEnum parse(String s) {
        for (DomandaBandoTabEnum val : DomandaBandoTabEnum.values()) {
            if (Objects.equals(val.key, s)) {
                return val;
            }
        }
        throw new RuntimeException("No enum val");
    }
}

