6534	            List<BandoForm> bandoForms, long domandaBandoId) {
6535	
6536	        // Recupero tutte le istanze della domanda
6537	        List<IstanzaDomandaBando> istanze = istanzaDomandaBandoLocalService
6538	                .getIstanzeDomandeBandoByDomandaBandoId(domandaBandoId);
6539	
6540	        // Mappa: formId → ultima istanza (per createDate, poi id per tie-break)
6541	        Map<Long, IstanzaDomandaBando> ultimaIstanzaPerForm = istanze.stream()
6542	                .collect(Collectors.toMap(
6543	                        IstanzaDomandaBando::getFormId,
6544	                        i -> i,
6545	                        (i1, i2) -> {
6546	                            int cmp = i1.getCreateDate().compareTo(i2.getCreateDate());
6547	                            return (cmp > 0 || (cmp == 0 && i1.getIstanzaDomandaBandoId() > i2.getIstanzaDomandaBandoId()))
6548	                                    ? i1 : i2;
6549	                        }
6550	                ));
6551	
6552	        //Preload Form per evitare N+1
6553	        Map<Long, Form> formMap = bandoForms.stream()
6554	                .map(BandoForm::getFormId)
6555	                .distinct()
6556	                .map(formLocalService::fetchForm)
6557	                .filter(Objects::nonNull)
6558	                .collect(Collectors.toMap(Form::getFormId, f -> f));
6559	
6560	        Set<String> codiciFormDaMostrare = new HashSet<>();
6561	
6562	        // Itero solo i BandoForm di tipo ESECUZIONE
6563	        for (BandoForm bandoForm : bandoForms.stream()
6564	                .filter(bf -> TipoFormEnum.ESECUZIONE.name().equals(bf.getTipoForm()))
6565	                .collect(Collectors.toList())) {
6566	
6567	            IstanzaDomandaBando ultimaIstanza = ultimaIstanzaPerForm.get(bandoForm.getFormId());
6568	
6569	            // Nessuna istanza → ESCLUDI
6570	            if (ultimaIstanza == null) {
6571	                continue;
6572	            }
6573	
6574	            // Stato non valido → ESCLUDI
6575	            if (!"INTEGRATA".equals(ultimaIstanza.getStato()) &&
6576	                    !"CONFERMATA".equals(ultimaIstanza.getStato())) {
6577	                continue;
